import {
    type SierraWebConfig,
    type AttachmentHandlerOpts,
    type MessageAttachment,
} from "@sierra/web";
import { useAttachmentHandlerChaining } from "./hooks";
import { memoRenderRoot, safeJSONParse, type ReactWebAttachmentDeclaration } from "./util";
import { withOpenAIAttachments, initializeOpenAIStandalone } from "./openai";

export function Attachments({
    attachmentTypes,
    attachments,
    opts,
}: {
    attachmentTypes: ReactWebAttachmentDeclaration<any>[];
    attachments: MessageAttachment[];
    opts: AttachmentHandlerOpts;
}) {
    const handledTypes = attachmentTypes.map(declaration => declaration.type);
    const [handledAttachments, restElement] = useAttachmentHandlerChaining(
        handledTypes,
        attachments,
        opts
    );

    return (
        <>
            {handledAttachments.map((attachment, i) => {
                const data = safeJSONParse<{ type: string }>(attachment.data);
                if (!data) {
                    return null;
                }
                const matchingType = attachmentTypes.find(
                    declaration => declaration.type === data.type
                );
                if (matchingType) {
                    return matchingType.render(data, opts);
                }
                return null;
            })}
            {restElement}
        </>
    );
}

export function defaultReactWebConfig(
    types: ReactWebAttachmentDeclaration<any>[]
): () => SierraWebConfig {
    const AttachmentsWithOpenAI = withOpenAIAttachments(Attachments);
    initializeOpenAIStandalone(opts => (
        <AttachmentsWithOpenAI attachmentTypes={types} attachments={[]} opts={opts} />
    ));
    return () => ({
        attachmentHandler: (attachments, opts) => {
            memoRenderRoot(
                opts.containerElement,
                <Attachments attachmentTypes={types} attachments={attachments} opts={opts} />
            );
        },
        attachmentTypes: types,
    });
}
